const char* warp_mma_name(int variant,const megafmm::Problem& p) {
  if(variant==51 || variant==52) {
    if(p.lda%8!=0 || p.ldb%8!=0)return "dense_cublaslt";
    const int columns=variant==51 ? 32:16;
    return p.m%128==0 && p.n%(2*columns)==0 && p.k%64==0 &&
           uint64_t(p.lda)<(uint64_t(1)<<39) && uint64_t(p.ldb)<(uint64_t(1)<<39) ?
           (variant==51 ? "megakernel_wgmma_psplit_tma_inplace_ss_64x32":"megakernel_wgmma_psplit_tma_inplace_ss_64x16"):
           "megakernel_warp_mma_packed";
  }

bool psplit_tma_inplace_ss_route_enabled(int variant) {
  require(variant==51 || variant==52,"inplace SS route requires51/52");
  static int cached[2]={-1,-1};
  if(cached[variant-51]>=0)return cached[variant-51]!=0;
  int enabled_dtypes=0,disabled_dtypes=0;
  for(auto dtype:{megafmm::DType::BF16,megafmm::DType::FP16}) {
    auto p=problem(128,variant==51 ? 64:32,64,dtype);
    megafmm::Policy policy;policy.algorithm=megafmm::Algorithm::Megakernel;
    policy.mega_variant=variant;policy.certified_range=true;policy.workspace_limit=0;
    try {
      auto plan=megafmm::create_plan(p,policy);
      require(plan->algorithm_name()==warp_mma_name(variant,p) && plan->workspace_bytes()==0,
              "inplace SS registered route silently substituted another algorithm");
      ++enabled_dtypes;
    } catch(const std::invalid_argument& e) {
      const std::string message=e.what();
      if(message.find("disabled")==std::string::npos || message.find(std::to_string(variant))==std::string::npos)throw;
      ++disabled_dtypes;
    }
  }
  require(enabled_dtypes==2 || disabled_dtypes==2,"inplace SS enable state differs between dtypes");
  cached[variant-51]=enabled_dtypes==2;
  std::cout << "TMA_INPLACE_SS_ROUTE_SCOPE variant=" << variant << " enabled=" << cached[variant-51]
            << " dtypes=2 metadata_only=1 native_runs=0\n";
  return cached[variant-51]!=0;
}
void psplit_tma_inplace_ss_blocked_policy_suite(int variant) {
  require(!psplit_tma_inplace_ss_route_enabled(variant),"inplace SS blocked policy requires explicitly disabled route");
  size_t rejected_cases=0,auto_dense_cases=0;
  for(auto dtype:{megafmm::DType::BF16,megafmm::DType::FP16}) {
    megafmm::Policy policy;policy.algorithm=megafmm::Algorithm::Megakernel;
    policy.mega_variant=variant;policy.certified_range=true;policy.workspace_limit=0;
    for(int scenario=0;scenario<4;++scenario) {
      auto p=problem(128,variant==51 ? 64:32,64,dtype);
      if(scenario==1)p.m=0;if(scenario==2)p.alpha=0;if(scenario==3)p.k=0;
      bool rejected=false;
      try {auto plan=megafmm::create_plan(p,policy);}
      catch(const std::invalid_argument& e) {
        const std::string message=e.what();
        rejected=message.find("disabled")!=std::string::npos && message.find(std::to_string(variant))!=std::string::npos;
      }
      require(rejected,"disabled inplace SS accepted before normal/empty/alpha0/K0 dispatch");
      ++rejected_cases;
    }
    policy.algorithm=megafmm::Algorithm::Auto;
    auto p=problem(128,variant==51 ? 64:32,64,dtype);
    require(megafmm::create_plan(p,policy)->algorithm_name()=="dense_cublaslt","Auto inplace SS metadata did not retain Dense policy");
    ++auto_dense_cases;
  }
  std::cout << "PASS_WGMMA_" << wgmma_scheduled_family(variant) << "_BLOCKED_POLICY variant=" << variant
            << " forced_rejections=" << rejected_cases << " validate_before_empty_scale=1 auto_dense_dtypes=" << auto_dense_cases << " native_runs=0\n";
}
void psplit_tma_inplace_ss_stride_metadata_suite(int variant) {
  constexpr int64_t limit=int64_t(1)<<39;
  const int columns=variant==51 ? 32:16;
  size_t cases=0,native_cases=0,packed_cases=0,dense_cases=0,setup_success=0,setup_unavailable=0;
  for(auto dtype:{megafmm::DType::BF16,megafmm::DType::FP16})
  for(int scenario=0;scenario<10;++scenario) {
    auto p=problem(128,2*columns,64,dtype);
    if(scenario==0)p.lda=limit-8;
    if(scenario==1)p.lda=limit;
    if(scenario==2)p.lda=limit+8;
    if(scenario==3)p.lda=limit+1;
    if(scenario==4)p.ldb=limit-8;
    if(scenario==5)p.ldb=limit;
    if(scenario==6)p.ldb=limit+8;
    if(scenario==7)p.ldb=limit+1;
    if(scenario==8)p.lda=p.ldb=limit-8;
    if(scenario==9)p.lda=p.ldb=limit;
    const size_t a_span=(size_t(p.m-1)*size_t(p.lda)+size_t(p.k))*2;
    const size_t b_span=(size_t(p.k-1)*size_t(p.ldb)+size_t(p.n))*2;
    require(a_span<(size_t(1)<<48) && b_span<(size_t(1)<<48),"inplace SS metadata span is not safely bounded");
    const bool native=scenario==0 || scenario==4 || scenario==8;
    require(megafmm::wgmma_psplit_tma_inplace_ss_can_implement(p,columns,0)==native,"inplace SS guard incorrectly handles both A/B stride bounds");
    const char* expected=warp_mma_name(variant,p);
    std::cout << "BEGIN_WGMMA_" << wgmma_scheduled_family(variant) << "_STRIDE_METADATA dtype=" << megafmm::dtype_name(dtype)
              << " variant=" << variant << " scenario=" << scenario << " lda=" << p.lda << " ldb=" << p.ldb
              << " expected=" << expected << " native_guard=" << native
              << " safe_a_span_bytes=" << a_span << " safe_b_span_bytes=" << b_span << " metadata_only=1 native_runs=0" << std::endl;
    megafmm::Policy policy;policy.algorithm=megafmm::Algorithm::Megakernel;
    policy.mega_variant=variant;policy.certified_range=true;policy.workspace_limit=0;
    std::unique_ptr<megafmm::Plan> plan;std::string setup_message;
    try {plan=megafmm::create_plan(p,policy);}
    catch(const std::runtime_error& error) {
      setup_message=error.what();
      if(setup_message.find("query Lt heuristics:")!=0 && setup_message.find("create matrix layout:")!=0 &&
         setup_message.find("cuBLASLt has no valid heuristic for this problem")==std::string::npos)throw;
    }
    if(plan) {
      require(plan->algorithm_name()==expected,"inplace SS Plan stride boundary route differs before encode");
      if(native || (scenario!=3 && scenario!=7))require(plan->workspace_bytes()==0,"metadata native/P7 route unexpectedly allocated workspace");
    } else std::cout << "SETUP_UNAVAILABLE_WGMMA_" << wgmma_scheduled_family(variant) << "_STRIDE_METADATA dtype=" << megafmm::dtype_name(dtype)
                     << " variant=" << variant << " scenario=" << scenario << " message=" << setup_message << '\n';
    std::cout << "META_WGMMA_" << wgmma_scheduled_family(variant) << "_STRIDE_METADATA dtype=" << megafmm::dtype_name(dtype)
              << " variant=" << variant << " scenario=" << scenario << " lda=" << p.lda << " ldb=" << p.ldb
              << " actual=" << (plan ? plan->algorithm_name():"setup_unavailable") << " setup_supported=" << bool(plan)
              << " expected=" << expected << " native_guard=" << native << " safe_a_span_bytes=" << a_span << " safe_b_span_bytes=" << b_span
              << " metadata_only=1 allocated_input_bytes=0 tensor_map_encodes=0 native_runs=0\n";
    ++cases;native_cases+=native;packed_cases+=!native && scenario!=3 && scenario!=7;dense_cases+=scenario==3 || scenario==7;
    setup_success+=bool(plan);setup_unavailable+=!plan;
  }
  std::cout << "PASS_WGMMA_" << wgmma_scheduled_family(variant) << "_STRIDE_METADATA variant=" << variant << " cases=" << cases
            << " native_guard_cases=" << native_cases << " packed_guard_cases=" << packed_cases << " dense_guard_cases=" << dense_cases
            << " setup_success_cases=" << setup_success << " setup_unavailable_cases=" << setup_unavailable
            << " native_helper_guards_all_checked=1 Plan_setup_claimed_only_if_supported=1 A_and_B_limit=549755813888"
            << " both_bounds_applied=1 metadata_only=1 allocated_input_bytes=0 tensor_map_encodes=0 native_runs=0\n";
}
